\label{ass:smooth}
The function $f:\mathbb R^{d_x}\times\mathbb R^{d_y}\to\mathbb R$ is twice continuously differentiable. For all ${\bf w},{\bf v}\in\mathbb R^{d_x+d_y}$, we assume that
\begin{equation}\label{eq:smooth}
\lVert \nabla^2f({\bf w})\rVert\le L~~~\text{and}~~~
\lVert \nabla^2f({\bf w})-\nabla^2f({\bf v})\rVert\le\rho\lVert {\bf w}-{\bf v}\rVert,
\end{equation}
where $L,\rho>0$.

\label{lem:cubic}
Let $g:\mathbb R^d\to\mathbb R$ be twice continuously differentiable with a $\rho_g$-Lipschitz Hessian, where $\rho_g>0$, and suppose $g({\bf z}_0)-\inf_{{\bf z}}g({\bf z})\le\Delta$. If the derivative routine satisfies~\eqref{eq:model-contract} at every iterate, then Algorithm~\ref{alg:inexact-crn} returns ${\bf z}_{K+1}$ after $K+1$ iterations, where
\begin{equation}\label{eq:cubic-sum}
K\le4\cdot8^{\frac{3}{2}}\Delta\sqrt{\rho_g}\,\varepsilon^{-\frac{3}{2}}
\quad\text{and}\quad
\sum_{k=0}^{K-1}\lVert {\bf s}_k\rVert^3\le\frac{4\Delta}{\rho_g}.
\end{equation}
Its output satisfies
\begin{equation}\label{eq:cubic-stop}
\lVert \nabla g({\bf z}_{K+1})\rVert<\frac{\varepsilon}{2}
\quad\text{and}\quad
\nabla^2g({\bf z}_{K+1})\succeq-\frac{3}{4}\sqrt{\rho_g\varepsilon}\,{\bf I}_d.
\end{equation}

\label{prop:primal}
Under Assumptions~\ref{ass:smooth}--\ref{ass:concave}, the regularized objective in~\eqref{eq:regularized-objective} has the following properties.
\begin{enumerate}[label=(\roman*),leftmargin=2em,itemsep=3pt]
\item For every ${\bf z}\in\mathbb R^{d_x}$, $f_{{\bf z}}(\cdot)$ is $L$-strongly convex in ${\bf u}$ and $\mu$-strongly concave in ${\bf y}$, and has the unique saddle point~\eqref{eq:saddle-map}. Its Hessian is nonsingular, with
\begin{equation}\label{eq:regularized-inverse-bound}
\lVert \bigl(\nabla^2f_{{\bf z}}({\bf w})\bigr)^{-1}\rVert\le \mu^{-1}.
\end{equation}
\item For every ${\bf z}\in\mathbb R^{d_x}$ and every ${\bf w},{\bf v}\in\mathbb R^{d_x+d_y}$, we have
\begin{equation}\label{eq:regularized-hessian-bounds}
\begin{aligned}
\lVert \nabla^2f_{{\bf z}}({\bf w})\rVert\le 3L~~~\text{and}~~~\lVert \nabla^2f_{{\bf z}}({\bf w})-\nabla^2f_{{\bf z}}({\bf v})\rVert\le\rho\lVert {\bf w}-{\bf v}\rVert.
\end{aligned}
\end{equation}
\end{enumerate}

\label{prop:envelope-basic}
Under Assumptions~\ref{ass:smooth}--\ref{ass:concave}, the envelope $\Phi_{2L}(\cdot)$ is twice continuously differentiable, with
\begin{equation}\label{eq:envelope-basic}
\nabla\Phi_{2L}({\bf z})=2L\bigl({\bf z}-{\bf u}^*({\bf z})\bigr)=\nabla\Phi({\bf u}^*({\bf z}))
\end{equation}
and
\begin{equation}\label{eq:envelope-hessian}
\nabla^2\Phi_{2L}({\bf z})=2L{\bf I}_{d_x}-4L^2{\bf M}({\bf w}^*({\bf z}))^{-1},
\end{equation}
where ${\bf M}({\bf w})$ is defined by
\begin{equation}\label{eq:schur-complement}
{\bf M}({\bf w}):=\nabla^2_{uu}f({\bf w})+2L{\bf I}_{d_x}
-\nabla^2_{uy}f({\bf w})\bigl(\nabla^2_{yy}f({\bf w})\bigr)^{-1}\nabla^2_{yu}f({\bf w}).
\end{equation}
For every ${\bf w}\in\mathbb R^{d_x+d_y}$, we have ${\bf M}({\bf w})\succeq L{\bf I}_{d_x}$. The envelope has the following properties.
\begin{enumerate}[label=(\roman*),leftmargin=2em,itemsep=3pt]
\item Its infimum is $\inf_{{\bf z}}\Phi_{2L}({\bf z})=\inf_{{\bf z}}\Phi({\bf z})$. 
Under Assumption~\ref{ass:gap}, we have $\Phi_{2L}({\bf z}_0)-\inf_{{\bf z}}\Phi_{2L}({\bf z})\le\Delta$.
\item If ${\bf z}$ is an $(\varepsilon,\eta)$-second-order stationary point of $\Phi_{2L}(\cdot)$, then ${\bf u}^*({\bf z})$ is an $(\varepsilon,2L\eta/(2L+\eta))$-second-order stationary point of $\Phi(\cdot)$, and hence also an $(\varepsilon,\eta)$-second-order stationary point.
\end{enumerate}

\label{lem:saddle-map}
Under Assumptions~\ref{ass:smooth}--\ref{ass:concave}, the saddle-point map ${\bf w}^*(\cdot)$ is continuously differentiable and for every ${\bf z},{\bf z}'\in\mathbb R^{d_x}$, it holds that
\begin{equation}\label{eq:global-displacement}
\lVert {\bf w}^*({\bf z})-{\bf w}^*({\bf z}')\rVert
\le \sqrt{4+\kappa}\lVert {\bf z}-{\bf z}'\rVert.
\end{equation}
Moreover, its distance from any point ${\bf w}\in\mathbb R^{d_x+d_y}$ is bounded by the gradient norm:
\begin{equation}\label{eq:residual-to-distance}
\lVert {\bf w}-{\bf w}^*({\bf z})\rVert\le \mu^{-1}\lVert \nabla f_{{\bf z}}({\bf w})\rVert.
\end{equation}

\label{lem:envelope}
Under Assumptions~\ref{ass:smooth}--\ref{ass:concave}, the Hessian of $\Phi_{2L}(\cdot)$ is $\widetilde{\rho}$-Lipschitz continuous, where $\widetilde{\rho}:=\rho(4+\kappa)^{3/2}$. Specifically, for every ${\bf z},{\bf z}'\in\mathbb R^{d_x}$,
\begin{equation}\label{eq:H}
\lVert \nabla^2\Phi_{2L}({\bf z})-\nabla^2\Phi_{2L}({\bf z}')\rVert
\le\widetilde{\rho}\lVert {\bf z}-{\bf z}'\rVert.
\end{equation}

We write ${\bf P}:=[2L{\bf I}_{d_x},{\bf 0}_{d_x\times d_y}]^\top$. 
Block elimination gives
\[
4L^2{\bf M}({\bf w})^{-1}={\bf P}^\top\bigl(\nabla^2f_{{\bf z}}({\bf w})\bigr)^{-1}{\bf P}.
\]
Thus, for any points ${\bf w},{\bf v}$, the inverse-difference identity gives
\begin{equation}\label{eq:envelope-hessian-difference}
\begin{aligned}
&4L^2\bigl({\bf M}({\bf v})^{-1}-{\bf M}({\bf w})^{-1}\bigr)\\
&\quad={\bf P}^\top\bigl(\nabla^2f_{{\bf z}}({\bf w})\bigr)^{-1}
\bigl(\nabla^2f_{{\bf z}}({\bf w})-\nabla^2f_{{\bf z}}({\bf v})\bigr)
\bigl(\nabla^2f_{{\bf z}}({\bf v})\bigr)^{-1}{\bf P}.
\end{aligned}
\end{equation}
Using~\eqref{eq:envelope-hessian-difference} and symmetry of the Hessians, we have
\begin{equation}\label{eq:schur-inverse-lipschitz}
\begin{aligned}
&4L^2\lVert {\bf M}({\bf v})^{-1}-{\bf M}({\bf w})^{-1}\rVert\\
&\quad\le
\lVert \bigl(\nabla^2f_{{\bf z}}({\bf w})\bigr)^{-1}{\bf P}\rVert
\lVert \nabla^2f_{{\bf z}}({\bf w})-\nabla^2f_{{\bf z}}({\bf v})\rVert
\lVert \bigl(\nabla^2f_{{\bf z}}({\bf v})\bigr)^{-1}{\bf P}\rVert\\
&\quad\stackrel{\eqref{eq:T-bound}}{\le}
(4+\kappa)\lVert \nabla^2f_{{\bf z}}({\bf w})-\nabla^2f_{{\bf z}}({\bf v})\rVert\\
&\quad\stackrel{\eqref{eq:regularized-hessian-bounds}}{\le}
\rho (4+\kappa)\lVert {\bf w}-{\bf v}\rVert.
\end{aligned}
\end{equation}
Apply \eqref{eq:schur-inverse-lipschitz} with ${\bf w}={\bf w}^*({\bf z})$ and ${\bf v}={\bf w}^*({\bf z}')$ yields
\[
\begin{aligned}
&\lVert \nabla^2\Phi_{2L}({\bf z})-\nabla^2\Phi_{2L}({\bf z}')\rVert\overset{\eqref{eq:envelope-hessian}}{\leq} 4L^2\lVert {\bf M}({\bf v})^{-1}-{\bf M}({\bf w})^{-1}\rVert
\\
&~~~\overset{\eqref{eq:schur-inverse-lipschitz}}{\le}\rho (4+\kappa)\lVert {\bf w}^*({\bf z})-{\bf w}^*({\bf z}')\rVert
\overset{\eqref{eq:global-displacement}}{\le}\rho (4+\kappa)^{\frac{3}{2}}\lVert {\bf z}-{\bf z}'\rVert.
\end{aligned}
\]
This proves~\eqref{eq:H}.

\label{lem:pce-dm}
Under Assumptions~\ref{ass:smooth}--\ref{ass:concave}, let $D_{\rm init}:=\lVert {\bf w}_{\rm init}-{\bf w}^*({\bf z})\rVert$. When the initial gradient norm exceeds $\bar\varepsilon$, Algorithm~\ref{alg:pce-dm} reaches~\eqref{eq:inner-target} within $T_{\rm PCE}(\bar\varepsilon)$ iterations and at most $2T_{\rm PCE}(\bar\varepsilon)+1$ gradient evaluations, where
\begin{equation}\label{eq:pce-horizon}
T_{\rm PCE}(\bar\varepsilon):=\Bigl\lceil720\sqrt\kappa
\log\frac{2592L^2\kappa^{\frac{3}{2}}D_{\rm init}^2}{\bar\varepsilon^2}\Bigr\rceil.
\end{equation}

\label{lem:local-newton}
Under Assumptions~\ref{ass:smooth}--\ref{ass:concave}, suppose
\begin{equation}\label{eq:local-newton-condition}
\lVert {\bf w}_{\rm init}-{\bf w}^*({\bf z})\rVert\le\frac{\mu}{12\rho}.
\end{equation}
When the initial gradient norm exceeds $\bar\varepsilon$, Algorithm~\ref{alg:newton} reaches~\eqref{eq:inner-target} using at most $T_{\rm N}(\bar\varepsilon)$ Hessian evaluations and $T_{\rm N}(\bar\varepsilon)+1$ gradient evaluations, where
\begin{equation}\label{eq:local-newton-horizon}
T_{\rm N}(\bar\varepsilon):=
\left\lceil\log_2\log_2\frac{6L\mu}{\rho\bar\varepsilon}\right\rceil.
\end{equation}

\label{lem:warm-start}
Under Assumptions~\ref{ass:smooth}--\ref{ass:concave}, choose $R,\bar\varepsilon$ such that
\begin{equation}\label{eq:tracking-conditions}
0<\bar\varepsilon\le\frac{\mu^2}{48\rho}
\quad\text{and}\quad
0<R\le\frac{\mu}{16\rho\sqrt{4+\kappa}}.
\end{equation}
If $\lVert \nabla f_{\bar{{\bf z}}}(\bar{{\bf w}})\rVert\le\bar\varepsilon$ and $\lVert {\bf z}-\bar{{\bf z}}\rVert\le R$, then
\begin{equation}\label{eq:warm-radius}
\lVert \bar{{\bf w}}-{\bf w}^*({\bf z})\rVert\le\frac{\mu}{12\rho}.
\end{equation}

By~\eqref{eq:residual-to-distance} and~\eqref{eq:global-displacement}, we have
\[
\begin{aligned}
\lVert \bar{{\bf w}}-{\bf w}^*({\bf z})\rVert
&\le\lVert \bar{{\bf w}}-{\bf w}^*(\bar{{\bf z}})\rVert+\lVert {\bf w}^*(\bar{{\bf z}})-{\bf w}^*({\bf z})\rVert\\
&\le \frac{\bar\varepsilon}{\mu}+\sqrt{4+\kappa}R
\le\frac{\mu}{48\rho}+\frac{\mu}{16\rho}
=\frac{\mu}{12\rho}.
\end{aligned}
\]

\label{lem:oracle}
Under Assumptions~\ref{ass:smooth}--\ref{ass:concave}, let $\varepsilon>0$ and set
\begin{equation}\label{eq:parameters}
\widetilde\varepsilon:=\min\Bigl\{\frac{\mu\varepsilon}{256L},\
\frac{\mu\sqrt{\widetilde{\rho}\varepsilon}}{128\rho(4+\kappa)},\
\frac{\mu^2}{48\rho},\
\frac{\mu\sqrt{\widetilde{\rho}\varepsilon}}{4\rho(1+\kappa)^3}\Bigr\}.
\end{equation}
For any point ${\bf w}=({\bf u},{\bf y})$ satisfying $\lVert \nabla f_{{\bf z}}({\bf w})\rVert\le\widetilde\varepsilon$, we define
\begin{equation}\label{eq:approx-derivatives}
\widehat{{\bf g}}:=2L({\bf z}-{\bf u})
\quad\text{and}\quad
\widehat{{\bf H}}:=2L{\bf I}_{d_x}-4L^2{\bf M}({\bf w})^{-1}.
\end{equation}
Then, it holds that the matrix $\widehat{{\bf H}}$ is symmetric and the derivative errors satisfy
\begin{equation}\label{eq:model-errors}
\lVert \widehat{{\bf g}}-\nabla\Phi_{2L}({\bf z})\rVert\le\frac{\varepsilon}{128}
\quad\text{and}\quad
\lVert \widehat{{\bf H}}-\nabla^2\Phi_{2L}({\bf z})\rVert\le\frac{\sqrt{\widetilde{\rho}\varepsilon}}{128}.
\end{equation}

Moreover, if ${\bf z}$ is an $(\varepsilon/2,3\sqrt{\widetilde{\rho}\varepsilon}/4)$-second-order stationary point of $\Phi_{2L}(\cdot)$, then ${\bf u}$ is an $(\varepsilon,\sqrt{\widetilde{\rho}\varepsilon})$-second-order stationary point of $\Phi(\cdot)$.

\label{thm:upper}
Under Assumptions~\ref{ass:smooth}--\ref{ass:gap}, for every $0<\varepsilon\le L^2/\widetilde{\rho}$, {\rm ECRN} returns an $(\varepsilon,\sqrt{\widetilde{\rho}\varepsilon})$-second-order stationary point of $\Phi(\cdot)$. 
Its total number of gradient and Hessian evaluations satisfies
\begin{equation}\label{eq:main-complexity}
N_{\rm grad}+N_{\rm Hess}
=\widetilde{\mathcal O}\!\left(
\Delta\sqrt\rho\,\kappa^{\frac{3}{4}}\varepsilon^{-\frac{3}{2}}\right).
\end{equation}

Let $K$ be the index at which ECRN satisfies its stopping condition, $r_k=\lVert {\bf s}_k\rVert$, and $m_k=\lceil r_k/R\rceil$. Lemma~\ref{lem:pce-dm}, applied to the initialization with $\bar\varepsilon=\widetilde\varepsilon$, and the stopping test in Algorithm~\ref{alg:pce-dm} give
\[
\lVert \nabla f_{{\bf z}_0}({\bf w}_0)\rVert\le\widetilde\varepsilon.
\]
The parameter choices satisfy
\[
\widetilde\varepsilon\stackrel{\eqref{eq:parameters}}{\le}\frac{\mu^2}{48\rho}
\quad\text{and}\quad
R=\frac{\mu}{48\rho\sqrt\kappa}
\le\frac{\mu}{16\rho\sqrt{4+\kappa}}.
\]
Applying Lemma~\ref{lem:tracking} with $\bar\varepsilon=\widetilde\varepsilon$ and $(\bar{{\bf w}},\bar{{\bf z}},{\bf z})=({\bf w}_k,{\bf z}_k,{\bf z}_{k+1})$ inductively yields
\[
\lVert \nabla f_{{\bf z}_k}({\bf w}_k)\rVert\le\widetilde\varepsilon~~~\text{for}~~~ k=0,\ldots,K+1.
\]
For each $k=0,\ldots,K$, Lemma~\ref{lem:oracle} gives
\[
\lVert \widehat{{\bf g}}_k-\nabla\Phi_{2L}({\bf z}_k)\rVert\stackrel{\eqref{eq:model-errors}}{\le}\frac{\varepsilon}{128}
\quad\text{and}\quad
\lVert \widehat{{\bf H}}_k-\nabla^2\Phi_{2L}({\bf z}_k)\rVert\stackrel{\eqref{eq:model-errors}}{\le}\frac{\sqrt{\widetilde{\rho}\varepsilon}}{128}.
\]
By Proposition~\ref{prop:envelope-basic}, we also have
\[
\Phi_{2L}({\bf z}_0)-\inf_{{\bf z}}\Phi_{2L}({\bf z})
=\Phi_{2L}({\bf z}_0)-\inf_{{\bf z}}\Phi({\bf z})
\stackrel{\eqref{eq:envelope}}{\le}\Phi({\bf z}_0)-\inf_{{\bf z}}\Phi({\bf z})\le\Delta.
\]
Applying Lemma~\ref{lem:cubic} with $g(\cdot)=\Phi_{2L}(\cdot)$ and $\rho_g=\widetilde{\rho}$ yields
\begin{equation}\label{eq:nonterminal-step-bounds}
K\stackrel{\eqref{eq:cubic-sum}}{\le}4\cdot8^{\frac{3}{2}}\Delta\sqrt{\widetilde{\rho}}\,\varepsilon^{-\frac{3}{2}}
\quad\text{and}\quad
\sum_{k=0}^{K-1}r_k^3\stackrel{\eqref{eq:cubic-sum}}{\le}\frac{4\Delta}{\widetilde{\rho}}.
\end{equation}
At iteration $K$, Lemma~\ref{lem:cubic} gives
\[
\lVert \nabla\Phi_{2L}({\bf z}_{K+1})\rVert\stackrel{\eqref{eq:cubic-stop}}{<}\frac{\varepsilon}{2}
\quad\text{and}\quad
\nabla^2\Phi_{2L}({\bf z}_{K+1})
\stackrel{\eqref{eq:cubic-stop}}{\succeq}-\frac{3}{4}\sqrt{\widetilde{\rho}\varepsilon}\,{\bf I}_{d_x}.
\]
The stationarity conclusion of Lemma~\ref{lem:oracle}, applied with ${\bf z}={\bf z}_{K+1}$ and ${\bf w}={\bf w}_{K+1}$, yields
\[
\lVert \nabla\Phi({\bf u}_{K+1})\rVert\le\varepsilon
\quad\text{and}\quad
\nabla^2\Phi({\bf u}_{K+1})\succeq-\sqrt{\widetilde{\rho}\varepsilon}\,{\bf I}_{d_x}.
\]
Then, we bound the total oracle complexity of ECRN.
The definitions of $R$ and $\widetilde{\rho}$, together with $\varepsilon\le L^2/\widetilde{\rho}$, give
\begin{align}
\label{eq:delta-R-bound-1}
&\frac{\sqrt{\varepsilon}}{R\sqrt{\widetilde{\rho}}}
=\frac{\sqrt{\widetilde{\rho}\varepsilon}}{\widetilde{\rho}R}
\le\frac{L}{\widetilde{\rho}R}
=48\left(\frac{\kappa}{4+\kappa}\right)^{\frac{3}{2}}\le48,
\end{align}
which gives
\begin{align}
\label{eq:delta-R-bound-2}
\frac{\Delta}{R\varepsilon}
=\frac{\sqrt{\varepsilon}}{R\sqrt{\widetilde{\rho}}}
\Delta\sqrt{\widetilde{\rho}}\,\varepsilon^{-\frac{3}{2}}
\stackrel{\eqref{eq:delta-R-bound-1}}{\le}48\Delta\sqrt{\widetilde{\rho}}\,\varepsilon^{-\frac{3}{2}}.
\end{align}
For $k=0,\ldots,K-1$, the stopping condition is not satisfied, so $r_k>\sqrt{\varepsilon/(8\widetilde{\rho})}$. Thus, it holds that
\begin{equation}\label{eq:r_k_bound}
r_k=\frac{r_k^3}{r_k^2}\le\frac{8\widetilde{\rho}}{\varepsilon}r_k^3.
\end{equation}
The number of segments in NewtonTrack method satisfies that
\begin{equation}\label{eq:m_k_bound}
m_k=\left\lceil \frac{r_k}{R}\right\rceil\le1+\frac{r_k}{R}.
\end{equation}
Summing up \eqref{eq:m_k_bound} gives
\begin{equation}\label{eq:nonterminal-segments}
\begin{aligned}
\sum_{k=0}^{K-1}m_k
&\stackrel{\eqref{eq:m_k_bound}}{\le}K+\frac{1}{R}\sum_{k=0}^{K-1}r_k\stackrel{\eqref{eq:r_k_bound}}{\le}
K+\frac{8\widetilde{\rho}}{R\varepsilon}\sum_{k=0}^{K-1}r_k^3\\
&\stackrel{\eqref{eq:nonterminal-step-bounds}}{\le}
K+\frac{32\Delta}{R\varepsilon}\stackrel{\eqref{eq:nonterminal-step-bounds},\eqref{eq:delta-R-bound-2}}{=}
\mathcal O(\Delta\sqrt{\widetilde{\rho}}\,\varepsilon^{-\frac{3}{2}}).
\end{aligned}
\end{equation}
At iteration $K$, the stopping test gives $r_K\le\sqrt{\varepsilon/(8\widetilde{\rho})}$. Thus, we have
\[
m_K\stackrel{\eqref{eq:m_k_bound}}{\le}1+\frac{r_K}{R}
\le1+\frac{\sqrt{\varepsilon}}{\sqrt8R\sqrt{\widetilde{\rho}}}
\stackrel{\eqref{eq:delta-R-bound-1}}{\le}1+\frac{48}{\sqrt8}.
\]
Consequently, the total number of inner solves performed by NewtonTrack is
\begin{equation}\label{eq:total-segments}
N_{\rm seg}:=\sum_{k=0}^{K}m_k
=\mathcal O\bigl(\Delta\sqrt{\widetilde{\rho}}\,\varepsilon^{-\frac{3}{2}}\bigr).
\end{equation}
The initialization cost from Lemma~\ref{lem:pce-dm} and the per-call evaluation counts from Lemma~\ref{lem:tracking} give the final oracle complexity
\[
\begin{aligned}
&N_{\rm grad}+N_{\rm Hess}\\
&\quad\stackrel{\eqref{eq:local-newton-horizon}}{\le}
\underbrace{\widetilde{\mathcal O}(\sqrt\kappa)}_{\text{PCE-DM}}+\underbrace{K+1}_{\text{outer level}}
+\underbrace{\left(2\left\lceil\log_2\log_2\frac{6L\mu}{\rho\widetilde\varepsilon}\right\rceil+1\right)N_{\rm seg}}_{\text{inner level}}\\
&\quad\stackrel{\eqref{eq:cubic-sum}}{\le}\widetilde{\mathcal O}(\sqrt\kappa)+ \mathcal{O}(\Delta \sqrt{\tilde{\rho}}\epsilon^{-\frac{3}{2}})
+\mathcal O\!\left(N_{\rm seg}\log\log\frac{L\mu}{\rho\widetilde\varepsilon}\right)\\
&\quad \stackrel{\eqref{eq:total-segments}}{\le} \tilde{O}(\Delta\sqrt\rho\,\kappa^{\frac{3}{4}}\varepsilon^{-\frac{3}{2}} ).
\end{aligned}
\]

\label{dfn:so-alg-class}
Let ${\mathbb{O}}({\bf w}) = (\nabla f({\bf w}), \nabla^2 f({\bf w}))$ be the second-order oracle.
A deterministic second-order algorithm \texttt{A} consists of a sequence of measurable mappings $\{ \texttt{A}^{(t)} \}_{t \in {\mathbb{N}}}$ such that $\texttt{A}^{(t)}$ takes in the first $t-1$ oracle responses  to produce the $t$-th query,  \textit{i.e.}, \texttt{A} generates a sequence $\{{\bf w}^{(t)}\}_{t \in {\mathbb{N}}}$ with
\begin{align*}
    {\bf w}^{(t)} = \texttt{A}^{(t)} ( {\mathbb{O}}({\bf w}^{(0)}), {\mathbb{O}}({\bf w}^{(1)}), \cdots, {\mathbb{O}}({\bf w}^{(t-1)}) ).
\end{align*}

\label{lem:pro-psi}
If $c_\varepsilon\le L/8$, the function $\psi({\bf y}) = Q^*(\beta {\bf y})$ satisfies
\begin{equation}\label{eq:psi-bounds-main}
\mu {\bf I}_T \preceq\nabla^2\psi({\bf y})\preceq\frac{5}{3}\mu {\bf I}_T~~~\text{and}~~~
\operatorname{Lip}(\nabla^2\psi({\bf y}))\le\frac{\beta^3\rho_h}{(\frac{L}{2}-c_\varepsilon)^3},
\end{equation}
where $\operatorname{Lip}(\,\cdot\,)$ denotes the Lipschitz constant of a matrix.

\label{lem:zero-chain}
If $ G \alpha \le L\sigma^2/4$ and $\operatorname{supp}({\bf y})\subseteq\{1,\ldots,k\}$, then
\begin{equation}\label{eq:oracle-support}
\operatorname{supp}(\nabla\psi({\bf y}))\subseteq\{1,\ldots,k+1\}~~~\text{and}~~~
\operatorname{supp} \left(\nabla^2\psi({\bf y})-\frac{2\beta^2}{L} {\bf I}_T\right)
\subseteq \{1,\ldots,k+1\}^2.
\end{equation}

\label{thm:lower}
There exists a universal constant $c>0$ such that the following statement holds. Let $L\ge16\mu>0$, $\rho>0$, $\Delta>0$, and $0<\varepsilon\le cL^2/(\rho\kappa^{3/2})$.
For every deterministic second-order algorithm, there is a function of the form \eqref{eq:rotated-instance} satisfying Assumptions~\ref{ass:smooth}--\ref{ass:gap}, with ${\bf z}_0={\bf 0}$, on which the algorithm needs at least
\begin{equation}\label{eq:lower-bound}
T = \Omega \left( \Delta\sqrt\rho\,\kappa^{\frac{3}{4}}\varepsilon^{-\frac{3}{2}}\right)
\end{equation}
queries before it can guarantee $\lVert \nabla\Phi_{\bf U}({\bf x}^{(t)})\rVert\le\varepsilon$.

We specialize \citet[Lemmas~2--3]{wang2019inexact} to the cubic parameter $M=2\rho_g$ and the errors in~\eqref{eq:model-contract}. Writing $r_k=\lVert {\bf s}_k\rVert$, their Taylor and cubic-model estimates give
\begin{equation}\label{eq:inexact-decrease}
\begin{aligned}
&g({\bf z}_k)-g({\bf z}_{k+1})
\ge\frac{\rho_g}{3}r_k^3-\frac{\varepsilon}{128}r_k
-\frac{\sqrt{\rho_g\varepsilon}}{256}r_k^2,\\
&\lVert \nabla g({\bf z}_{k+1})\rVert
\le\frac{3\rho_g}{2}r_k^2+\frac{\sqrt{\rho_g\varepsilon}}{128}r_k+\frac{\varepsilon}{128},\\
\text{and}\qquad&\nabla^2g({\bf z}_{k+1})
\succeq-\Bigl(2\rho_g r_k+\frac{\sqrt{\rho_g\varepsilon}}{128}\Bigr){\bf I}_d.
\end{aligned}
\end{equation}
Whenever $r_k>\sqrt{\varepsilon/(8\rho_g)}$, we have
\begin{equation}\label{eq:cubic-decrease}
\begin{aligned}
g({\bf z}_k)-g({\bf z}_{k+1})
&\stackrel{\eqref{eq:inexact-decrease}}{\ge}
\frac{\rho_g}{3}r_k^3-\frac{\varepsilon}{128}r_k-\frac{\sqrt{\rho_g\varepsilon}}{256}r_k^2\\
&\quad {\ge}
\rho_g\Bigl(\frac{1}{3}-\frac{8}{128}-\frac{\sqrt8}{256}\Bigr)r_k^3
\ge\frac{\rho_g}{4}r_k^3.
\end{aligned}
\end{equation}
If the stopping condition is not satisfied at $k=0,\ldots,N-1$, then
\begin{equation}\label{eq:cubic-telescope}
\begin{aligned}
\frac{N\varepsilon^{\frac{3}{2}}}{4\cdot8^{\frac{3}{2}}\sqrt{\rho_g}}
&\le\frac{\rho_g}{4}\sum_{k=0}^{N-1}r_k^3
\stackrel{\eqref{eq:cubic-decrease}}{\le}
\sum_{k=0}^{N-1}\bigl(g({\bf z}_k)-g({\bf z}_{k+1})\bigr)\\
&=g({\bf z}_0)-g({\bf z}_N)\le\Delta.
\end{aligned}
\end{equation}
Thus the stopping condition can fail at most $4\cdot8^{3/2}\Delta\sqrt{\rho_g}\,\varepsilon^{-3/2}$ times. Let $K$ be the first index such that $r_K\le\sqrt{\varepsilon/(8\rho_g)}$. Taking $N=K$ in~\eqref{eq:cubic-telescope} proves both bounds in~\eqref{eq:cubic-sum}. At iteration $K$, we have
\[
\begin{aligned}
&\lVert \nabla g({\bf z}_{K+1})\rVert
\stackrel{\eqref{eq:inexact-decrease}}{\le}
\frac{3\rho_g}{2}r_K^2+\frac{\sqrt{\rho_g\varepsilon}}{128}r_K+\frac{\varepsilon}{128}
\le\Bigl(\frac{3}{16}+\frac{1}{128\sqrt8}+\frac{1}{128}\Bigr)\varepsilon<\frac{\varepsilon}{2},\\
\text{and}\qquad&\nabla^2g({\bf z}_{K+1})
\stackrel{\eqref{eq:inexact-decrease}}{\succeq}
-\Bigl(2\rho_g r_K+\frac{\sqrt{\rho_g\varepsilon}}{128}\Bigr){\bf I}_d\succeq-\Bigl(\frac{1}{\sqrt2}+\frac{1}{128}\Bigr)\sqrt{\rho_g\varepsilon}\,{\bf I}_d
\succeq-\frac{3}{4}\sqrt{\rho_g\varepsilon}\,{\bf I}_d.
\end{aligned}
\]
This proves~\eqref{eq:cubic-stop}.

\emph{(i)} The Hessian blocks satisfy
\begin{equation}\label{eq:regularized-block-bounds}
\begin{aligned}
&\nabla^2_{uu}f_{{\bf z}}({\bf w})
\stackrel{\eqref{eq:regularized-derivatives}}{=}
\nabla^2_{uu}f({\bf w})+2L{\bf I}_{d_x}
\stackrel{\eqref{eq:smooth}}{\succeq}L{\bf I}_{d_x}~~~
\text{and}~~~\nabla^2_{yy}f_{{\bf z}}({\bf w})
\stackrel{\eqref{eq:regularized-derivatives}}{=}
\nabla^2_{yy}f({\bf w})
{\preceq}-\mu{\bf I}_{d_y}.
\end{aligned}
\end{equation}
Thus $f_{{\bf z}}(\cdot)$ is $L$-strongly convex in ${\bf u}$ and $\mu$-strongly concave in ${\bf y}$. 
This gives $\lVert \bigl(\nabla^2 f_{{\bf z}}({\bf w})\bigr)^{-1}\rVert\le \mu^{-1}$.
Its unique saddle point~\eqref{eq:saddle-map} exists by \citet[Lemma~1.1 and Theorem~1.2]{grimmer2023landscape}, applied globally to $f_{{\bf z}}(\cdot)$.













\emph{(ii)} We have
\[
\begin{aligned}
&\lVert \nabla^2f_{{\bf z}}({\bf w})\rVert
\stackrel{\eqref{eq:regularized-derivatives}}{\le}
\lVert \nabla^2f({\bf w})\rVert+2L
\stackrel{\eqref{eq:smooth}}{\le}3L\\
\text{and}\qquad&\lVert \nabla^2f_{{\bf z}}({\bf w})-\nabla^2f_{{\bf z}}({\bf v})\rVert
\stackrel{\eqref{eq:regularized-derivatives}}{=}
\lVert \nabla^2f({\bf w})-\nabla^2f({\bf v})\rVert
\stackrel{\eqref{eq:smooth}}{\le}\rho\lVert {\bf w}-{\bf v}\rVert.
\end{aligned}
\]

Equation~(10) in \citet{grimmer2023landscape}, with proximal parameter $2L$, gives the gradient identity~\eqref{eq:envelope-basic}.
By~\eqref{eq:regularized-inverse-bound}, the implicit function theorem applied to $\nabla f_{{\bf z}}({\bf w}^*({\bf z}))={\bf 0}_{d_x+d_y}$ gives ${\bf w}^*(\cdot)\in C^1$ with
\begin{equation}\label{eq:saddle-jacobian}
\begin{aligned}
\frac{\partial{\bf w}^*({\bf z})}{\partial{\bf z}}
&=\bigl(\nabla^2f_{{\bf z}}({\bf w}^*({\bf z}))\bigr)^{-1}
\begin{pmatrix}2L{\bf I}_{d_x}\\{\bf 0}_{d_y\times d_x}\end{pmatrix}\\
&\!\!\!\!\!\stackrel{\eqref{eq:regularized-derivatives},\eqref{eq:schur-complement}}{=}
2L\begin{pmatrix}
{\bf M}({\bf w}^*({\bf z}))^{-1}\\
-\bigl(\nabla^2_{yy}f({\bf w}^*({\bf z}))\bigr)^{-1}\nabla^2_{yu}f({\bf w}^*({\bf z})){\bf M}({\bf w}^*({\bf z}))^{-1}
\end{pmatrix}.
\end{aligned}
\end{equation}
The Schur complement satisfies
\[
{\bf M}({\bf w})
\stackrel{\eqref{eq:schur-complement},\eqref{eq:regularized-block-bounds}}{\succeq}
\nabla^2_{uu}f({\bf w})+2L{\bf I}_{d_x}
\stackrel{\eqref{eq:regularized-block-bounds}}{\succeq}L{\bf I}_{d_x}.
\]
In addition, \eqref{eq:saddle-jacobian} gives
\begin{equation}\label{eq:sensitivity}
\frac{\partial{\bf u}^*({\bf z})}{\partial{\bf z}}
{=}
2L{\bf M}({\bf w}^*({\bf z}))^{-1}.
\end{equation}
Differentiating the gradient identity gives
\[
\nabla^2\Phi_{2L}({\bf z})
\stackrel{\eqref{eq:envelope-basic}}{=}
2L{\bf I}_{d_x}-2L\frac{\partial{\bf u}^*({\bf z})}{\partial{\bf z}}
\stackrel{\eqref{eq:sensitivity}}{=}
2L{\bf I}_{d_x}-4L^2{\bf M}({\bf w}^*({\bf z}))^{-1},
\]
which proves~\eqref{eq:envelope-hessian} and $\Phi_{2L}(\cdot)\in C^2$.

\emph{(i)} Equation~(9) in \citet{grimmer2023landscape} gives
\begin{equation}\label{eq:envelope-value-upper}
\Phi_{2L}({\bf z})\le\Phi({\bf z}).
\end{equation}
Moreover,
\begin{equation}\label{eq:envelope-value-bounds}
\inf_{{\bf z}}\Phi_{2L}({\bf z})
\stackrel{\eqref{eq:envelope}}{=}
\inf_{{\bf u}}\Bigl\{\Phi({\bf u})+\inf_{{\bf z}}L\lVert {\bf u}-{\bf z}\rVert^2\Bigr\}
=\inf_{{\bf u}}\Phi({\bf u}).
\end{equation}
Hence
\[
\Phi_{2L}({\bf z}_0)-\inf_{{\bf z}}\Phi_{2L}({\bf z})
\stackrel{\eqref{eq:envelope-value-upper},\eqref{eq:envelope-value-bounds}}{\le}
\Phi({\bf z}_0)-\inf_{{\bf z}}\Phi({\bf z}) {\le}\Delta.
\]

\emph{(ii)} Proposition~1 in \citet{chen2023cubic} gives
\begin{equation}\label{eq:primal-schur-hessian}
\nabla^2\Phi({\bf u}^*({\bf z}))={\bf M}({\bf w}^*({\bf z}))-2L{\bf I}_{d_x}.
\end{equation}
Suppose $\lVert \nabla\Phi_{2L}({\bf z})\rVert\le\varepsilon$ and $\nabla^2\Phi_{2L}({\bf z})\succeq-\eta{\bf I}_{d_x}$. Then
\begin{equation}\label{eq:envelope-inverse-curvature}
4L^2{\bf M}({\bf w}^*({\bf z}))^{-1}
\stackrel{\eqref{eq:envelope-hessian}}{=}
2L{\bf I}_{d_x}-\nabla^2\Phi_{2L}({\bf z})
\preceq(2L+\eta){\bf I}_{d_x}.
\end{equation}
Since ${\bf M}({\bf w}^*({\bf z}))\succeq L{\bf I}_{d_x}$, we obtain
\[
\begin{aligned}
&\nabla^2\Phi({\bf u}^*({\bf z}))
\stackrel{\eqref{eq:primal-schur-hessian}}{=}
{\bf M}({\bf w}^*({\bf z}))-2L{\bf I}_{d_x}
\stackrel{\eqref{eq:envelope-inverse-curvature}}{\succeq}
\Bigl(\frac{4L^2}{2L+\eta}-2L\Bigr){\bf I}_{d_x}=-\frac{2L\eta}{2L+\eta}{\bf I}_{d_x}\succeq-\eta{\bf I}_{d_x}\\
\end{aligned}
\]
and
\begin{align*}
    \lVert \nabla\Phi({\bf u}^*({\bf z}))\rVert
\stackrel{\eqref{eq:envelope-basic}}{=}\lVert \nabla\Phi_{2L}({\bf z})\rVert\le\varepsilon.
\end{align*}

As shown in the proof of Proposition~\ref{prop:envelope-basic}, ${\bf w}^*(\cdot)\in C^1$ and~\eqref{eq:saddle-jacobian} holds.
For every ${\bf w}\in\mathbb R^{d_x+d_y}$, we have
\begin{equation}\label{eq:inverse-upper-block}
\begin{aligned}
 \lVert 2L{\bf M}({\bf w})^{-1}\rVert^2
\le 4L^2\cdot L^{-2}=4,
\end{aligned}
\end{equation}
where we use ${\bf M}({\bf w})\succeq L{\bf I}_{d_x}$.
For the lower block, we have
\begin{equation}\label{eq:schur-block-bounds}
\begin{aligned}
\nabla^2_{uy}f({\bf w})\bigl(\nabla^2_{yy}f({\bf w})\bigr)^{-2}\nabla^2_{yu}f({\bf w}) &\preceq
-\mu^{-1}\nabla^2_{uy}f({\bf w})\bigl(\nabla^2_{yy}f({\bf w})\bigr)^{-1}\nabla^2_{yu}f({\bf w})\\
&\stackrel{\eqref{eq:schur-complement}}{=}
\mu^{-1}\bigl({\bf M}({\bf w})-\nabla^2_{uu}f({\bf w})-2L{\bf I}_{d_x}\bigr)\\
&\stackrel{\eqref{eq:regularized-block-bounds}}{\preceq}
\mu^{-1}\bigl({\bf M}({\bf w})-L{\bf I}_{d_x}\bigr).
\end{aligned}
\end{equation}
Moreover, we have
\begin{equation}\label{eq:schur-inverse-quadratic-bound}
\begin{aligned}
&{\bf 0}_{d_x\times d_x}
{\preceq}
{\bf M}({\bf w})^{-1}-L{\bf M}({\bf w})^{-2}=\frac{1}{4L}{\bf I}_{d_x}
-L\Bigl({\bf M}({\bf w})^{-1}-\frac{1}{2L}{\bf I}_{d_x}\Bigr)^2
\preceq\frac{1}{4L}{\bf I}_{d_x}.
\end{aligned}
\end{equation}
Thus the squared norm of the lower block satisfies
\begin{equation}\label{eq:inverse-lower-block}
\begin{aligned}
&\lVert 2L\bigl(\nabla^2_{yy}f({\bf w})\bigr)^{-1}\nabla^2_{yu}f({\bf w}){\bf M}({\bf w})^{-1}\rVert^2\\
&=4L^2\lVert {\bf M}({\bf w})^{-1}\nabla^2_{uy}f({\bf w})
\bigl(\nabla^2_{yy}f({\bf w})\bigr)^{-2}\nabla^2_{yu}f({\bf w}){\bf M}({\bf w})^{-1}\rVert\\
&\!\!\stackrel{\eqref{eq:schur-block-bounds}}{\le}
\frac{4L^2}{\mu}\lVert {\bf M}({\bf w})^{-1}
\bigl({\bf M}({\bf w})-L{\bf I}_{d_x}\bigr){\bf M}({\bf w})^{-1}\rVert\\
&=\frac{4L^2}{\mu}\lVert {\bf M}({\bf w})^{-1}-L{\bf M}({\bf w})^{-2}\rVert
\stackrel{\eqref{eq:schur-inverse-quadratic-bound}}{\le}
\frac{4L^2}{\mu}\cdot\frac{1}{4L}=\kappa.
\end{aligned}
\end{equation}
Combining the two block estimates gives
\begin{equation}\label{eq:T-bound}
\begin{aligned}
&\lVert \bigl(\nabla^2f_{{\bf z}}({\bf w})\bigr)^{-1}
\begin{pmatrix}2L{\bf I}_{d_x}\\{\bf 0}_{d_y\times d_x}\end{pmatrix}\rVert^2\\
&\quad\stackrel{\eqref{eq:regularized-derivatives},\eqref{eq:schur-complement}}{\le}
\lVert 2L{\bf M}({\bf w})^{-1}\rVert^2
+\lVert 2L\bigl(\nabla^2_{yy}f({\bf w})\bigr)^{-1}\nabla^2_{yu}f({\bf w}){\bf M}({\bf w})^{-1}\rVert^2\\
&\quad\stackrel{\eqref{eq:inverse-upper-block},\eqref{eq:inverse-lower-block}}{\le}4+\kappa.
\end{aligned}
\end{equation}
Integrating the derivative along the segment from ${\bf z}'$ to ${\bf z}$ yields
\[
\begin{aligned}
&\lVert {\bf w}^*({\bf z})-{\bf w}^*({\bf z}')\rVert
=\lVert \int_0^1\frac{\partial{\bf w}^*}{\partial{\bf z}}\bigl({\bf z}'+t({\bf z}-{\bf z}')\bigr)({\bf z}-{\bf z}')\,dt\rVert\stackrel{\eqref{eq:saddle-jacobian},\eqref{eq:T-bound}}{\le}
\sqrt{4+\kappa}\lVert {\bf z}-{\bf z}'\rVert.
\end{aligned}
\]
Finally, the distance to the saddle point satisfies
\[
\lVert {\bf w}-{\bf w}^*({\bf z})\rVert {\le}
\mu^{-1}\lVert \nabla f_{{\bf z}}({\bf w}) -\nabla f_{{\bf z}}({\bf w}^*({\bf z}))\rVert = \mu^{-1} \|\nabla f_{{\bf z}}({\bf w})\|,
\]
which proves~\eqref{eq:residual-to-distance}.

For ${\bf w}_0={\bf w}_{\rm init}$, equation~(24) in \citet{zhang2026near} gives
\begin{equation}\label{eq:pce-rate}
\lVert {\bf w}_t-{\bf w}^*({\bf z})\rVert^2
\le
288\kappa^{\frac{3}{2}}\Bigl(1+\frac{1}{360\sqrt\kappa}\Bigr)^{-t}D_{\rm init}^2.
\end{equation}
Since $\kappa\ge1$, we have
\begin{equation}\label{eq:pce-log-bound}
\log\Bigl(1+\frac{1}{360\sqrt\kappa}\Bigr)
\ge\frac{1}{360\sqrt\kappa+1}
\ge\frac{1}{720\sqrt\kappa}.
\end{equation}
Since $\nabla f_{{\bf z}}({\bf w}^*({\bf z}))={\bf 0}_{d_x+d_y}$, we have
\begin{equation}\label{eq:pce-gradient-rate}
\begin{aligned}
&\lVert \nabla f_{{\bf z}}({\bf w}_t)\rVert^2
\stackrel{\eqref{eq:regularized-hessian-bounds}}{\le}
9L^2\lVert {\bf w}_t-{\bf w}^*({\bf z})\rVert^2\\
&\quad\stackrel{\eqref{eq:pce-rate}}{\le}
2592L^2\kappa^{\frac{3}{2}}D_{\rm init}^2
\Bigl(1+\frac{1}{360\sqrt\kappa}\Bigr)^{-t}\\
&\quad\stackrel{\eqref{eq:pce-log-bound}}{\le}
2592L^2\kappa^{\frac{3}{2}}D_{\rm init}^2
\exp\Bigl(-\frac{t}{720\sqrt\kappa}\Bigr).
\end{aligned}
\end{equation}
Taking $t=T_{\rm PCE}(\bar\varepsilon)$ gives
\[
\begin{aligned}
&\lVert \nabla f_{{\bf z}}({\bf w}_{T_{\rm PCE}(\bar\varepsilon)})\rVert^2\\
&\quad\stackrel{\eqref{eq:pce-gradient-rate}}{\le}
2592L^2\kappa^{\frac{3}{2}}D_{\rm init}^2
\exp\Bigl(-\frac{T_{\rm PCE}(\bar\varepsilon)}{720\sqrt\kappa}\Bigr)\\
&\quad\stackrel{\eqref{eq:pce-horizon}}{\le}
2592L^2\kappa^{\frac{3}{2}}D_{\rm init}^2
\exp\Bigl(-\log\frac{2592L^2\kappa^{\frac{3}{2}}D_{\rm init}^2}{\bar\varepsilon^2}\Bigr)
=\bar\varepsilon^2.
\end{aligned}
\]
Each iteration evaluates the gradient at the predictor and at the new iterate, reusing the latter for the next stopping test and predictor. Including the initial query, the gradient count is at most
\[
2T_{\rm PCE}(\bar\varepsilon)+1
\stackrel{\eqref{eq:pce-horizon}}{=}\widetilde{\mathcal O}(\sqrt\kappa).
\]

Fix ${\bf z}$ and let ${\bf w}_t$ be the Newton iterates, with ${\bf w}_0={\bf w}_{\rm init}$. Since $\nabla f_{{\bf z}}({\bf w}^*({\bf z}))={\bf 0}_{d_x+d_y}$, Taylor's formula gives
\begin{equation}\label{eq:newton-taylor-remainder}
\lVert \nabla f_{{\bf z}}({\bf w}_t)-\nabla^2f_{{\bf z}}({\bf w}_t)({\bf w}_t-{\bf w}^*({\bf z}))\rVert
\stackrel{\eqref{eq:regularized-hessian-bounds}}{\le}
\frac{\rho}{2}\lVert {\bf w}_t-{\bf w}^*({\bf z})\rVert^2.
\end{equation}
The Newton update in Algorithm~\ref{alg:newton} therefore satisfies
\begin{equation}\label{eq:newton-error-recursion}
\begin{aligned}
&\lVert {\bf w}_{t+1}-{\bf w}^*({\bf z})\rVert\\
&\quad\stackrel{\eqref{eq:regularized-inverse-bound}}{\le}
\frac{1}{\mu}\lVert \nabla f_{{\bf z}}({\bf w}_t)-\nabla^2f_{{\bf z}}({\bf w}_t)({\bf w}_t-{\bf w}^*({\bf z}))\rVert\\
&\quad\stackrel{\eqref{eq:newton-taylor-remainder}}{\le}
\frac{\rho}{2\mu}\lVert {\bf w}_t-{\bf w}^*({\bf z})\rVert^2.
\end{aligned}
\end{equation}
For every $t\ge0$, it follows that
\begin{equation}\label{eq:newton-distance}
\begin{aligned}
&\lVert {\bf w}_t-{\bf w}^*({\bf z})\rVert
\stackrel{\eqref{eq:newton-error-recursion}}{\le}
\frac{2\mu}{\rho}\Bigl(\frac{\rho\lVert {\bf w}_0-{\bf w}^*({\bf z})\rVert}{2\mu}\Bigr)^{2^t}\stackrel{\eqref{eq:local-newton-condition}}{\le}
\frac{2\mu}{\rho}\,2^{-2^t}.
\end{aligned}
\end{equation}
Consequently, we have
\begin{equation}\label{eq:newton-residual-rate}
\lVert \nabla f_{{\bf z}}({\bf w}_t)\rVert
\stackrel{\eqref{eq:regularized-hessian-bounds}}{\le} 
3L\lVert {\bf w}_t-{\bf w}^*({\bf z})\rVert
\stackrel{\eqref{eq:newton-distance}}{\le}
\frac{6L\mu}{\rho}\,2^{-2^t}.
\end{equation}
Taking $t=T_{\rm N}(\bar\varepsilon)$ in the gradient bound gives
\[
\lVert \nabla f_{{\bf z}}({\bf w}_{T_{\rm N}(\bar\varepsilon)})\rVert
\stackrel{\eqref{eq:newton-residual-rate}}{\le}
\frac{6L\mu}{\rho}\,2^{-2^{T_{\rm N}(\bar\varepsilon)}}
\stackrel{\eqref{eq:local-newton-horizon}}{\le}\bar\varepsilon.
\]
Algorithm~\ref{alg:newton} therefore stops after at most $T_{\rm N}(\bar\varepsilon)$ updates.

We assume that 
\begin{equation}\label{eq:oracle-residual-assumption}
\lVert \nabla f_{{\bf z}}({\bf w})\rVert\le\widetilde\varepsilon.
\end{equation}
Hence, we have
\begin{equation}\label{eq:oracle-distance}
\lVert {\bf u}-{\bf u}^*({\bf z})\rVert
\le\lVert {\bf w}-{\bf w}^*({\bf z})\rVert
\stackrel{\eqref{eq:residual-to-distance}}{\le}
\frac{\lVert \nabla f_{{\bf z}}({\bf w})\rVert}{\mu}
\stackrel{\eqref{eq:oracle-residual-assumption}}{\le}
\frac{\widetilde\varepsilon}{\mu}.
\end{equation}
The gradient approximation satisfies
\[
\begin{aligned}
\lVert \widehat{{\bf g}}-\nabla\Phi_{2L}({\bf z})\rVert
\stackrel{\eqref{eq:approx-derivatives},\eqref{eq:envelope-basic}}{=}
2L\lVert {\bf u}-{\bf u}^*({\bf z})\rVert\stackrel{\eqref{eq:oracle-distance}}{\le}
\frac{2L\widetilde\varepsilon}{\mu}
\stackrel{\eqref{eq:parameters}}{\le}\frac{\varepsilon}{128}.
\end{aligned}
\]
The Schur complement ${\bf M}({\bf w})$ is symmetric, so $\widehat{{\bf H}}$ is symmetric by~\eqref{eq:approx-derivatives}. Its approximation error satisfies
\[
\begin{aligned}
\lVert \widehat{{\bf H}}-\nabla^2\Phi_{2L}({\bf z})\rVert
&\stackrel{\eqref{eq:approx-derivatives},\eqref{eq:envelope-hessian}}{=}
4L^2\lVert {\bf M}({\bf w}^*({\bf z}))^{-1}-{\bf M}({\bf w})^{-1}\rVert\\
&\quad\stackrel{\eqref{eq:schur-inverse-lipschitz}}{\le}
\rho(4+\kappa)\lVert {\bf w}-{\bf w}^*({\bf z})\rVert\\
&\quad\stackrel{\eqref{eq:oracle-distance}}{\le}
\frac{\rho(4+\kappa)\widetilde\varepsilon}{\mu}
\stackrel{\eqref{eq:parameters}}{\le}
\frac{\sqrt{\widetilde\rho\varepsilon}}{128},
\end{aligned}
\]
which proves~\eqref{eq:model-errors}.
We let $\bar{\bf y}:=\operatorname*{arg\,max}_{{\bf y}}f({\bf u},{\bf y})$ such that $\nabla_y f({\bf u},\bar{\bf y})={\bf 0}_{d_y}$, then we have
\begin{equation}\label{eq:oracle-dual-monotonicity}
\begin{aligned}
&\mu\lVert {\bf y}-\bar{\bf y}\rVert^2
{\le}
-\langle \nabla_y f({\bf u},{\bf y}),{\bf y}-\bar{\bf y}\rangle \le\lVert \nabla_y f({\bf u},{\bf y})\rVert\lVert {\bf y}-\bar{\bf y}\rVert.
\end{aligned}
\end{equation}
Thus, the dual error obeys
\begin{equation}\label{eq:oracle-dual-distance}
\begin{aligned}
&\lVert {\bf y}-\bar{\bf y}\rVert
\stackrel{\eqref{eq:oracle-dual-monotonicity}}{\le}
\frac{\lVert \nabla_y f({\bf u},{\bf y})\rVert}{\mu}\stackrel{\eqref{eq:regularized-derivatives}}{=}
\frac{\lVert \nabla_y f_{{\bf z}}({\bf w})\rVert}{\mu}
\stackrel{\eqref{eq:oracle-residual-assumption}}{\le}
\frac{\widetilde\varepsilon}{\mu}.
\end{aligned}
\end{equation}
Danskin's identity gives
\begin{equation}\label{eq:oracle-primal-gradient-decomposition}
\begin{aligned}
&\nabla\Phi({\bf u})-2L({\bf z}-{\bf u})\stackrel{\eqref{eq:regularized-derivatives}}{=}
\nabla_u f({\bf u},\bar{\bf y})-\nabla_u f({\bf u},{\bf y})
+\nabla_u f_{{\bf z}}({\bf w}).
\end{aligned}
\end{equation}
Thus, we have
\begin{equation}\label{eq:primal-gradient-error}
\begin{aligned}
&\lVert \nabla\Phi({\bf u})-\nabla\Phi_{2L}({\bf z})\rVert\\
&\quad\stackrel{\eqref{eq:envelope-basic}}{\le}
\lVert \nabla\Phi({\bf u})-2L({\bf z}-{\bf u})\rVert+2L\lVert {\bf u}-{\bf u}^*({\bf z})\rVert\\
&\quad\stackrel{\eqref{eq:oracle-primal-gradient-decomposition}}{\le}
\lVert \nabla_u f({\bf u},\bar{\bf y})-\nabla_u f({\bf u},{\bf y})\rVert
+\lVert \nabla_u f_{{\bf z}}({\bf w})\rVert+2L\lVert {\bf u}-{\bf u}^*({\bf z})\rVert\\
&\quad\stackrel{\eqref{eq:smooth}}{\le}
L\lVert {\bf y}-\bar{\bf y}\rVert+\lVert \nabla_u f_{{\bf z}}({\bf w})\rVert+2L\lVert {\bf u}-{\bf u}^*({\bf z})\rVert\\
&\!\!\!\!\!\!\!\!\!\quad\stackrel{\eqref{eq:oracle-dual-distance},\eqref{eq:oracle-residual-assumption},\eqref{eq:oracle-distance}}{\le}
\frac{L\widetilde\varepsilon}{\mu}+\widetilde\varepsilon+\frac{2L\widetilde\varepsilon}{\mu}
\le\frac{4L\widetilde\varepsilon}{\mu}.
\end{aligned}
\end{equation}
The Hessian formulas give
\begin{equation}\label{eq:oracle-exact-primal-curvature}
\begin{aligned}
&\nabla^2\Phi({\bf u}^*({\bf z}))-\nabla^2\Phi_{2L}({\bf z})\\
&\quad\stackrel{\eqref{eq:primal-schur-hessian},\eqref{eq:envelope-hessian}}{=}
\bigl({\bf M}({\bf w}^*({\bf z}))-2L{\bf I}_{d_x}\bigr)
{\bf M}({\bf w}^*({\bf z}))^{-1}
\bigl({\bf M}({\bf w}^*({\bf z}))-2L{\bf I}_{d_x}\bigr)
\succeq{\bf 0}_{d_x\times d_x}.
\end{aligned}
\end{equation}
Proposition~1 in \citet{chen2023cubic} gives
\begin{equation}\label{eq:oracle-primal-hessian-lipschitz}
\lVert \nabla^2\Phi({\bf u})-\nabla^2\Phi({\bf u}^*({\bf z}))\rVert{\le}
\rho(1+\kappa)^3\lVert {\bf u}-{\bf u}^*({\bf z})\rVert.
\end{equation}
Therefore, we have
\begin{equation}\label{eq:output-error}
\begin{aligned}
&\nabla^2\Phi({\bf u})\\
&\stackrel{\eqref{eq:oracle-primal-hessian-lipschitz}}{\succeq}
\nabla^2\Phi({\bf u}^*({\bf z}))
-\rho(1+\kappa)^3\lVert {\bf u}-{\bf u}^*({\bf z})\rVert\,{\bf I}_{d_x}\\
&\!\!\!\stackrel{\eqref{eq:oracle-exact-primal-curvature},\eqref{eq:oracle-distance}}{\succeq}
\nabla^2\Phi_{2L}({\bf z})
-\frac{\rho(1+\kappa)^3\widetilde\varepsilon}{\mu}\,{\bf I}_{d_x}.
\end{aligned}
\end{equation}
If ${\bf z}$ is an $(\epsilon/2, 3\sqrt{\widetilde{\rho}\epsilon}/4)$-SOSP such that 
\begin{equation}\label{eq:oracle-envelope-stationarity}
\begin{aligned}
\lVert \nabla\Phi_{2L}({\bf z})\rVert\le\frac{\varepsilon}{2}~~~
\text{and}~~~\nabla^2\Phi_{2L}({\bf z})
\succeq-\frac{3}{4}\sqrt{\widetilde\rho\varepsilon}\,{\bf I}_{d_x}.
\end{aligned}
\end{equation}
Then, for the computed point ${\bf w}= ({\bf u},{\bf y})$ satisfied \eqref{eq:oracle-residual-assumption}, we have
\begin{align*}
&\lVert \nabla\Phi({\bf u})\rVert\\
&\quad\le\lVert \nabla\Phi_{2L}({\bf z})\rVert
+\lVert \nabla\Phi({\bf u})-\nabla\Phi_{2L}({\bf z})\rVert\\
&\stackrel{\eqref{eq:oracle-envelope-stationarity},\eqref{eq:primal-gradient-error}}{\le}
\frac{\varepsilon}{2}+\frac{4L\widetilde\varepsilon}{\mu}
\stackrel{\eqref{eq:parameters}}{\le}\frac{\varepsilon}{2}+\frac{\varepsilon}{64}<\varepsilon
\end{align*}
and 
\begin{align*}
&\nabla^2\Phi({\bf u})\\
&\quad\stackrel{\eqref{eq:output-error}}{\succeq}
\nabla^2\Phi_{2L}({\bf z})
-\frac{\rho(1+\kappa)^3\widetilde\varepsilon}{\mu}\,{\bf I}_{d_x}\\
&\quad\stackrel{\eqref{eq:oracle-envelope-stationarity}}{\succeq}
-\Bigl(\frac{3}{4}\sqrt{\widetilde\rho\varepsilon}
+\frac{\rho(1+\kappa)^3\widetilde\varepsilon}{\mu}\Bigr){\bf I}_{d_x}\\
&\quad\stackrel{\eqref{eq:parameters}}{\succeq}
-\Bigl(\frac{3}{4}+\frac{1}{4}\Bigr)\sqrt{\widetilde\rho\varepsilon}\,{\bf I}_{d_x}
=-\sqrt{\widetilde\rho\varepsilon}\,{\bf I}_{d_x}.
\end{align*}
